(function(){"use strict";$(()=>{$(".language-wrapper .dropdown .dropdown-toggle").off("click").on("click",o=>{o.preventDefault();let e=$(o.currentTarget);e.hasClass("active")?(e.closest(".language-wrapper").find(".dropdown .dropdown-menu").hide(),e.removeClass("active")):(e.closest(".language-wrapper").find(".dropdown .dropdown-menu").show(),e.addClass("active"))}),$(document).on("click",o=>{let e=$(o.currentTarget);e.closest(".language-wrapper").length===0&&(e.closest(".language-wrapper").find(".dropdown .dropdown-menu").hide(),e.closest(".language-wrapper").find(".dropdown .dropdown-toggle").removeClass("active"))})})})();
